import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware to extract user context
app.use((req, res, next) => {
  req.userId = req.headers['x-user-id'];
  req.role = req.headers['x-user-role'] || 'viewer';
  next();
});

// Search endpoint with flexible filtering
app.get('/api/v2/documents/search', async (req, res) => {
  const { q, category, sort_by, order, limit } = req.query;

  let baseQuery = `SELECT id, title, category, created_at, owner_id, sensitivity_level
    FROM documents WHERE 1=1`;
  const params = [];
  let paramIdx = 1;

  if (q) {
    baseQuery += ` AND (title ILIKE $${paramIdx} OR content ILIKE $${paramIdx})`;
    params.push(`%${q}%`);
    paramIdx++;
  }

  if (category) {
    baseQuery += ` AND category = $${paramIdx}`;
    params.push(category);
    paramIdx++;
  }

  // Sort handling - sort_by is validated against allowed columns
  const allowedSorts = ['title', 'created_at', 'category'];
  const sortCol = allowedSorts.includes(sort_by) ? sort_by : 'created_at';
  const sortOrder = order === 'asc' ? 'ASC' : 'DESC';
  baseQuery += ` ORDER BY ${sortCol} ${sortOrder}`;

  // Limit handling
  const parsedLimit = parseInt(limit) || 50;
  baseQuery += ` LIMIT ${parsedLimit}`;

  try {
    const result = await pool.query(baseQuery, params);
    res.json({ documents: result.rows, count: result.rows.length });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Search failed' });
  }
});

// Bulk update endpoint
app.post('/api/v2/documents/bulk-update', async (req, res) => {
  const { document_ids, updates } = req.body;

  if (!document_ids || !Array.isArray(document_ids) || document_ids.length === 0) {
    return res.status(400).json({ error: 'document_ids required' });
  }

  // Build SET clause from updates object
  const setClauses = [];
  const params = [];
  let paramIdx = 1;

  const mutableFields = ['title', 'category', 'sensitivity_level', 'status'];

  for (const [field, value] of Object.entries(updates || {})) {
    if (mutableFields.includes(field)) {
      setClauses.push(`${field} = $${paramIdx}`);
      params.push(value);
      paramIdx++;
    }
  }

  if (setClauses.length === 0) {
    return res.status(400).json({ error: 'No valid updates provided' });
  }

  // Construct IN clause for document IDs
  const idPlaceholders = document_ids.map((id, i) => `$${paramIdx + i}`).join(',');
  params.push(...document_ids);

  const updateQuery = `UPDATE documents SET ${setClauses.join(', ')}, 
    updated_at = NOW(), updated_by = '${req.userId}'
    WHERE id IN (${idPlaceholders})`;

  try {
    const result = await pool.query(updateQuery, params);
    res.json({ updated: result.rowCount });
  } catch (err) {
    console.error('Bulk update error:', err.message);
    res.status(500).json({ error: 'Update failed' });
  }
});

// Export for reports
app.get('/api/v2/documents/export', async (req, res) => {
  const { format, filter_owner } = req.query;

  let query = 'SELECT * FROM documents';
  if (filter_owner) {
    query += ` WHERE owner_id = '${filter_owner}'`;
  }
  query += ' ORDER BY created_at DESC LIMIT 1000';

  try {
    const result = await pool.query(query);
    if (format === 'csv') {
      res.setHeader('Content-Type', 'text/csv');
      const csv = result.rows.map(r => Object.values(r).join(',')).join('\n');
      res.send(csv);
    } else {
      res.json({ documents: result.rows });
    }
  } catch (err) {
    res.status(500).json({ error: 'Export failed' });
  }
});

app.listen(3000, () => console.log('Document service running on :3000'));
